var n=`1279-callaloo-soup`;var t=`world-1279`;var a=`GD`;var o=`central-america-caribbean`;var s=4;var l=43;var r={en:`Callaloo Soup`,ua:`Суп калалу`};var d={en:`Callaloo Soup is a dish from Grenada featuring yellow onion, garlic, okra, spinach. This home-sized recipe records each ingredient at the step where it is used. Spinach replaces unavailable callaloo leaves.`,ua:`Суп калалу, страва кухні країни Гренада з такими основними складниками: жовта цибуля, часник, бамія, шпинат. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Шпинат замінює відсутнє в каталозі листя калалу.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`okra`,230,`g`],[`coconut-oil`,30,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 27 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 27 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:27,i:[[`spinach`,430,`g`],[`pumpkin`,320,`g`],[`coconut-milk`,550,`ml`],[`thyme`,3,`sprig`]]},{en:`Combine the prepared components from earlier steps gently into the intended final mixture; do not add new ingredients.`,ua:`Обережно змішайте раніше підготовлені компоненти в потрібну масу; нових складників на цьому етапі не додавайте.`,t:[`mixing`],m:5,i:[]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`]]}];var g={slug:n,id:t,country:`GD`,region:o,servings:4,minutes:43,title:r,text:d,steps:u};export{a as country,g as default,t as id,l as minutes,o as region,s as servings,n as slug,u as steps,d as text,r as title};